func phaseBadge(ph string) string {
	switch ph {
	case PhaseOpen:
		return "**open** — sealing"
	case PhaseReveal:
		return "**reveal** — secrets being opened"
	case PhaseDrawable:
		return "**drawable** — waiting for a draw"
	case PhaseDrawn:
		return "**drawn**"
	case PhaseCancelled:
		return "cancelled"
	}
	return ph
}

func phaseTick(active bool) string {
	if active {
		return "←"
	}
	return ""
}

func closeLine(e *Event, now int64) string {
	switch e.phase(now) {
	case PhaseOpen:
		return "in " + left(e.ClosesAt, now)
	case PhaseReveal:
		return "closed " + left(now, e.ClosesAt) + " ago"
	case PhaseDrawable:
		return "closed " + left(now, e.ClosesAt) + " ago"
	case PhaseDrawn:
		return "drawn " + left(now, e.DrawnAt) + " ago"
	case PhaseCancelled:
		return "cancelled"
	}
	return ""
}

// left renders a positive duration in seconds as "2d 3h", "4h 12m", "3m 40s".
func left(until int64, from int64) string {
	d := until - from
	if d < 0 {
		d = 0
	}
	if d >= 86400 {
		return strconv.FormatInt(d/86400, 10) + "d " + strconv.FormatInt((d%86400)/3600, 10) + "h"
	}
	if d >= 3600 {
		return strconv.FormatInt(d/3600, 10) + "h " + strconv.FormatInt((d%3600)/60, 10) + "m"
	}
	if d >= 60 {
		return strconv.FormatInt(d/60, 10) + "m " + strconv.FormatInt(d%60, 10) + "s"
	}
	return strconv.FormatInt(d, 10) + "s"
}

// stamp renders a unix second in both UTC and KST, the two clocks this board's
// audience reads.
func stamp(unix int64) string {
	t := time.Unix(unix, 0).UTC()
	k := time.Unix(unix+9*3600, 0).UTC()
	return t.Format("2006-01-02 15:04") + " / " + k.Format("01-02 15:04") + " KST"
}

func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-6:]
}

// cell keeps a free-text field from breaking a markdown table.
func cell(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '|' {
			out += "\\|"
		} else if c == '\n' || c == '\r' {
			out += " "
		} else {
			out += string(c)
		}
	}
	return out
}

func quoteList(items []string) string {
	out := ""
	for i := 0; i < len(items); i++ {
		if i > 0 {
			out += ", "
		}
		out += "\"" + items[i] + "\""
	}
	return out
}

func parseUint(s string) (uint64, bool) {
	if s == "" {
		return 0, false
	}
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

package hearthcore

import (
	"strconv"
	"strings"
)

// JSONBuilder constructs deterministic, RFC-8259-compliant JSON objects without
// reflection or external dependencies so realms can expose structured queries
// to AI agents and MCP servers via vm/qeval.
type JSONBuilder struct {
	b     strings.Builder
	count int
}

// NewJSONObject starts a new JSON object builder.
func NewJSONObject() *JSONBuilder {
	jb := &JSONBuilder{}
	jb.b.WriteByte('{')
	return jb
}

func (jb *JSONBuilder) writeKey(key string) {
	if jb.count > 0 {
		jb.b.WriteByte(',')
	}
	jb.b.WriteString(QuoteJSON(key))
	jb.b.WriteByte(':')
	jb.count++
}

// Str appends a string field.
func (jb *JSONBuilder) Str(key, val string) *JSONBuilder {
	jb.writeKey(key)
	jb.b.WriteString(QuoteJSON(val))
	return jb
}

// Int64 appends a signed 64-bit integer field.
func (jb *JSONBuilder) Int64(key string, val int64) *JSONBuilder {
	jb.writeKey(key)
	jb.b.WriteString(strconv.FormatInt(val, 10))
	return jb
}

// Uint64 appends an unsigned 64-bit integer field.
func (jb *JSONBuilder) Uint64(key string, val uint64) *JSONBuilder {
	jb.writeKey(key)
	jb.b.WriteString(strconv.FormatUint(val, 10))
	return jb
}

// Bool appends a boolean field.
func (jb *JSONBuilder) Bool(key string, val bool) *JSONBuilder {
	jb.writeKey(key)
	if val {
		jb.b.WriteString("true")
	} else {
		jb.b.WriteString("false")
	}
	return jb
}

// Raw appends a pre-encoded JSON value (array or nested object).
func (jb *JSONBuilder) Raw(key, rawJSON string) *JSONBuilder {
	jb.writeKey(key)
	jb.b.WriteString(rawJSON)
	return jb
}

// String closes and returns the encoded JSON object.
func (jb *JSONBuilder) String() string {
	return jb.b.String() + "}"
}

// JoinJSONArray joins pre-encoded JSON elements into a JSON array.
func JoinJSONArray(items []string) string {
	if len(items) == 0 {
		return "[]"
	}
	var b strings.Builder
	b.WriteByte('[')
	for i, item := range items {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(item)
	}
	b.WriteByte(']')
	return b.String()
}

// QuoteJSON encodes s as a valid RFC-8259 JSON string literal.
func QuoteJSON(s string) string {
	var b strings.Builder
	b.Grow(len(s) + 2)
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if c < 0x20 {
				b.WriteString(`\u00`)
				b.WriteByte(hexDigit(c >> 4))
				b.WriteByte(hexDigit(c & 0x0f))
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func hexDigit(n byte) byte {
	if n < 10 {
		return '0' + n
	}
	return 'a' + (n - 10)
}

