// Tier represents a builder or agent's earned on-chain reputation rank.
type Tier string

const (
	TierApprentice  Tier = "Apprentice"
	TierJourneyman  Tier = "Journeyman"
	TierMaster      Tier = "Master"
	TierGuildmaster Tier = "Guildmaster"
)

// ComputeTier deterministically assigns a reputation tier using pure integer math.
func ComputeTier(settledCount uint64, earnedUgnot int64, ratingSum uint64, ratingCount uint64) Tier {
	highQuality := ratingCount == 0 || ratingSum*10 >= ratingCount*45
	if (settledCount >= 10 || earnedUgnot >= 500*UgnotPerGNOT) && highQuality {
		return TierGuildmaster
	}
	if settledCount >= 5 || earnedUgnot >= 100*UgnotPerGNOT {
		return TierMaster
	}
	if settledCount >= 2 || earnedUgnot >= 10*UgnotPerGNOT {
		return TierJourneyman
	}
	return TierApprentice
}

// TierColor returns a high-contrast hex accent color for SVG badges.
func (t Tier) Color() string {
	switch t {
	case TierGuildmaster:
		return "#f59e0b"
	case TierMaster:
		return "#a78bfa"
	case TierJourneyman:
		return "#38bdf8"
	default:
		return "#34d399"
	}
}

// ComputeSplit splits an escrowed ugnot balance between hunter and sponsor
// using integer basis points (0..10000). It guarantees exact conservation:
// hunterUgnot + sponsorRefundUgnot == escrowUgnot.
func ComputeSplit(escrowUgnot int64, hunterBps uint64) (hunterUgnot int64, sponsorRefundUgnot int64) {
	if escrowUgnot < 0 {
		panic("hearthcore: negative escrow amount")
	}
	if hunterBps > MaxBps {
		panic("hearthcore: hunterBps exceeds 10000")
	}
	if hunterBps == 0 {
		return 0, escrowUgnot
	}
	if hunterBps == MaxBps {
		return escrowUgnot, 0
	}
	// Divide first to prevent int64 multiplication overflow on large balances.
	q := escrowUgnot / int64(MaxBps)
	r := escrowUgnot % int64(MaxBps)
	hunterUgnot = q*int64(hunterBps) + (r*int64(hunterBps))/int64(MaxBps)
	sponsorRefundUgnot = escrowUgnot - hunterUgnot
	return hunterUgnot, sponsorRefundUgnot
}

// FormatGNOT formats micro-GNOT into a deterministic human-readable GNOT string
// without floating-point operations.
func FormatGNOT(ugnot int64) string {
	neg := false
	if ugnot < 0 {
		neg = true
		ugnot = -ugnot
	}
	whole := ugnot / UgnotPerGNOT
	frac := ugnot % UgnotPerGNOT

	prefix := ""
	if neg {
		prefix = "-"
	}
	if frac == 0 {
		return prefix + strconv.FormatInt(whole, 10) + ".00 GNOT"
	}

	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	// Keep at least 2 decimal digits, trimming trailing zeros beyond 2.
	trimmed := strings.TrimRight(fracStr, "0")
	if len(trimmed) < 2 {
		trimmed = fracStr[:2]
	}
	return prefix + strconv.FormatInt(whole, 10) + "." + trimmed + " GNOT"
}

// FormatRating formats an integer rating sum/count into "X.Y / 5.0" or "Unrated".
func FormatRating(sum uint64, count uint64) string {
	if count == 0 {
		return "Unrated"
	}
	tenths := (sum*10 + count/2) / count
	whole := tenths / 10
	rem := tenths % 10
	return strconv.FormatUint(whole, 10) + "." + strconv.FormatUint(rem, 10) + " / 5.0"
}

// ShortAddr shortens a bech32 Gno address for compact tables and badges.
func ShortAddr(addr address) string {
	s := string(addr)
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-4:]
}

// EscapeMath neutralizes unescaped dollar signs after Markdown sanitization so
// gnoweb's math extension does not treat prices or user text as TeX formulas.
func EscapeMath(s string) string {
	return strings.ReplaceAll(s, "$", `\$`)
}

// NeutralizeGnoTags escapes any remaining <gno- or </gno- tag sequences
// (case-insensitive) as defense-in-depth on top of p/nt/markdown/sanitize/v0
// so user-authored text can never smuggle gnoweb UI directives.
func NeutralizeGnoTags(s string) string {
	lower := strings.ToLower(s)
	if !strings.Contains(lower, "<gno-") && !strings.Contains(lower, "</gno-") {
		return s
	}
	var b strings.Builder
	b.Grow(len(s) + 8)
	for i := 0; i < len(s); i++ {
		if s[i] == '<' {
			rem := lower[i:]
			if strings.HasPrefix(rem, "<gno-") || strings.HasPrefix(rem, "</gno-") {
				b.WriteString("&lt;")
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// ValidateText verifies a required or optional text field within rune/byte bounds.
func ValidateText(field, value string, minLen, maxLen int) string {
	trimmed := strings.TrimSpace(value)
	if len(trimmed) < minLen {
		panic("hearthcore: " + field + " is too short")
	}
	if len(trimmed) > maxLen {
		panic("hearthcore: " + field + " exceeds maximum length")
	}
	return trimmed
}

// ValidateProofURL enforces safe http/https/ipfs proof links.
func ValidateProofURL(raw string) string {
	trimmed := ValidateText("proof URL", raw, 8, MaxURLLen)
	if !strings.HasPrefix(trimmed, "https://") &&
		!strings.HasPrefix(trimmed, "http://") &&
		!strings.HasPrefix(trimmed, "ipfs://") {
		panic("hearthcore: proof URL must start with https://, http://, or ipfs://")
	}
	if strings.ContainsAny(trimmed, " \t\r\n") {
		panic("hearthcore: proof URL must not contain whitespace")
	}
	return trimmed
}

// ValidateProofDigest verifies a non-empty hexadecimal or prefixed content digest.
func ValidateProofDigest(raw string) string {
	trimmed := ValidateText("proof digest", raw, 8, MaxDigestLen)
	if strings.ContainsAny(trimmed, " \t\r\n") {
		panic("hearthcore: proof digest must not contain whitespace")
	}
	return trimmed
}

// ValidateDeadlineBlocks checks that a bounty deadline window is within safe bounds.
func ValidateDeadlineBlocks(blocks int64) int64 {
	if blocks == 0 {
		return DefaultDeadlineBlocks
	}
	if blocks < MinDeadlineBlocks || blocks > MaxDeadlineBlocks {
		panic("hearthcore: deadlineBlocks out of allowed range")
	}
	return blocks
}

// ValidateRating checks that a settlement rating is in [1, 5].
func ValidateRating(rating uint8) uint8 {
	if rating < 1 || rating > 5 {
		panic("hearthcore: rating must be between 1 and 5")
	}
	return rating
}

package hearthbounty

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
)

// SetArbiter transfers dispute-resolution authority to a new valid Gno address.
func SetArbiter(cur realm, next address) {
	caller := cur.Previous().Address()
	if caller != arbiter {
		panic("hearthbounty: only current arbiter may transfer arbiter role")
	}
	if !next.IsValid() {
		panic("hearthbounty: next arbiter address is invalid")
	}
	arbiter = next
	chain.Emit(
		"ArbiterUpdated",
		"previous", string(caller),
		"arbiter", string(next),
	)
}

// RegisterProfile creates or updates a builder or autonomous AI agent profile.
// Providing a non-empty agentEndpoint marks the profile as an MCP-capable AI agent.
func RegisterProfile(cur realm, handle, bio, skills, agentEndpoint string) {
	caller := cur.Previous().Address()
	cleanHandle := hearthcore.ValidateText("handle", handle, 2, hearthcore.MaxHandleLen)
	cleanBio := hearthcore.ValidateText("bio", bio, 0, hearthcore.MaxBioLen)
	cleanSkills := hearthcore.ValidateText("skills", skills, 0, hearthcore.MaxSkillsLen)
	cleanEndpoint := hearthcore.ValidateText("agentEndpoint", agentEndpoint, 0, hearthcore.MaxEndpointLen)

	p := getOrCreateProfile(caller, runtime.ChainHeight())
	wasAgent := p.IsAgent
	p.Handle = cleanHandle
	p.Bio = cleanBio
	p.Skills = cleanSkills
	p.AgentEndpoint = cleanEndpoint
	p.IsAgent = cleanEndpoint != ""

	if !wasAgent && p.IsAgent {
		agentCount++
	} else if wasAgent && !p.IsAgent {
		agentCount--
	}

	chain.Emit(
		"ProfileRegistered",
		"address", string(caller),
		"handle", cleanHandle,
		"is_agent", strconv.FormatBool(p.IsAgent),
	)
}

// PostBounty creates a new micro-bounty funded with attached ugnot escrow.
// Requires a direct EOA call (AssertOriginCall + cur.Previous().IsUserCall()).
func PostBounty(cur realm, title, spec, category string, deadlineBlocks int64) uint64 {
	runtime.AssertOriginCall()
	if !cur.Previous().IsUserCall() {
		panic("hearthbounty: direct EOA call required to fund escrow")
	}

	amount := requireSingleUgnotSend(hearthcore.MinRewardUgnot)
	cleanTitle := hearthcore.ValidateText("title", title, 4, hearthcore.MaxTitleLen)
	cleanSpec := hearthcore.ValidateText("spec", spec, 10, hearthcore.MaxSpecLen)
	cat, ok := hearthcore.ParseCategory(category)
	if !ok {
		panic("hearthbounty: invalid category (use realm, tool, audit, docs, or agent)")
	}
	blocks := hearthcore.ValidateDeadlineBlocks(deadlineBlocks)

	sponsor := cur.Previous().Address()
	height := runtime.ChainHeight()
	nextID := uint64(bountySeq.Next())

	rec := &bountyRecord{
		ID:             nextID,
		Title:          cleanTitle,
		Spec:           cleanSpec,
		Category:       cat,
		Status:         hearthcore.StatusOpen,
		Sponsor:        sponsor,
		EscrowUgnot:    amount,
		InitialUgnot:   amount,
		DeadlineBlocks: blocks,
		CreatedHeight:  height,
	}

	bounties.Set(bountyKey(nextID), rec)
	openCount++
	totalEscrowUgnot += amount

	sp := getOrCreateProfile(sponsor, height)
	sp.PostedCount++
	sp.SponsoredUgnot += amount

	chain.Emit(
		"BountyPosted",
		"id", strconv.FormatUint(nextID, 10),
		"sponsor", string(sponsor),
		"category", string(cat),
		"escrow_ugnot", strconv.FormatInt(amount, 10),
		"deadline_blocks", strconv.FormatInt(blocks, 10),
	)

	return nextID
}

// TopUpBounty allows any supporter to crowd-fund additional ugnot into an open
// or claimed bounty's escrow pool.
func TopUpBounty(cur realm, id uint64) int64 {
	runtime.AssertOriginCall()
	if !cur.Previous().IsUserCall() {
		panic("hearthbounty: direct EOA call required to top up escrow")
	}

	amount := requireSingleUgnotSend(1)
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen && b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: can only top up open or claimed bounties")
	}

	donor := cur.Previous().Address()
	b.EscrowUgnot += amount
	b.TopUpCount++
	totalEscrowUgnot += amount

	dp := getOrCreateProfile(donor, runtime.ChainHeight())
	dp.SponsoredUgnot += amount

	chain.Emit(
		"BountyToppedUp",
		"id", strconv.FormatUint(id, 10),
		"donor", string(donor),
		"added_ugnot", strconv.FormatInt(amount, 10),
		"escrow_ugnot", strconv.FormatInt(b.EscrowUgnot, 10),
	)

	return b.EscrowUgnot
}

// ClaimBounty reserves an open bounty for a builder or autonomous AI agent.
// Sponsors cannot claim their own bounty to preserve reputation integrity.
func ClaimBounty(cur realm, id uint64, agentNote string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen {
		panic("hearthbounty: bounty is not open for claiming")
	}

	caller := cur.Previous().Address()
	if caller == b.Sponsor {
		panic("hearthbounty: sponsor cannot claim own bounty")
	}
	cleanNote := hearthcore.ValidateText("agentNote", agentNote, 0, hearthcore.MaxNoteLen)

	height := runtime.ChainHeight()
	transitionStatus(b, hearthcore.StatusClaimed)
	b.Claimant = caller
	b.ClaimNote = cleanNote
	b.ClaimedHeight = height
	b.DeadlineHeight = height + b.DeadlineBlocks

	hp := getOrCreateProfile(caller, height)
	hp.ClaimedCount++

	chain.Emit(
		"BountyClaimed",
		"id", strconv.FormatUint(id, 10),
		"claimant", string(caller),
		"deadline_height", strconv.FormatInt(b.DeadlineHeight, 10),
	)
}

// ReleaseExpiredClaim returns a claimed bounty to Open when either the claimant
// voluntarily steps down or the deterministic block-height deadline has elapsed.
func ReleaseExpiredClaim(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: bounty is not currently claimed")
	}

	caller := cur.Previous().Address()
	height := runtime.ChainHeight()
	if caller != b.Claimant && height <= b.DeadlineHeight {
		panic("hearthbounty: claim deadline has not expired yet")
	}

	prevClaimant := b.Claimant
	transitionStatus(b, hearthcore.StatusOpen)
	b.Claimant = ""
	b.ClaimNote = ""
	b.ClaimedHeight = 0
	b.DeadlineHeight = 0
	b.RevisionFeedback = ""

	chain.Emit(
		"ClaimReleased",
		"id", strconv.FormatUint(id, 10),
		"previous_claimant", string(prevClaimant),
		"released_by", string(caller),
	)
}

// SubmitProof records a verifiable deliverable URL, cryptographic digest, and
// implementation summary for review by the sponsor.
func SubmitProof(cur realm, id uint64, proofURL, proofDigest, summary string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusClaimed {
		panic("hearthbounty: bounty must be claimed before submitting proof")
	}

	caller := cur.Previous().Address()
	if caller != b.Claimant {
		panic("hearthbounty: only the active claimant may submit proof")
	}

	cleanURL := hearthcore.ValidateProofURL(proofURL)
	cleanDigest := hearthcore.ValidateProofDigest(proofDigest)
	cleanSummary := hearthcore.ValidateText("summary", summary, 6, hearthcore.MaxNoteLen)

	transitionStatus(b, hearthcore.StatusSubmitted)
	b.ProofURL = cleanURL
	b.ProofDigest = cleanDigest
	b.ProofSummary = cleanSummary
	b.SubmittedHeight = runtime.ChainHeight()
	b.SubmissionCount++
	b.RevisionFeedback = ""

	chain.Emit(
		"ProofSubmitted",
		"id", strconv.FormatUint(id, 10),
		"claimant", string(caller),
		"proof_digest", cleanDigest,
		"submission_count", strconv.FormatUint(b.SubmissionCount, 10),
	)
}

// RequestRevision lets the sponsor send a submitted bounty back to Claimed with
// actionable feedback and a refreshed deadline window.
func RequestRevision(cur realm, id uint64, feedback string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: bounty has no pending submission")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may request a revision")
	}

	cleanFeedback := hearthcore.ValidateText("feedback", feedback, 4, hearthcore.MaxNoteLen)
	transitionStatus(b, hearthcore.StatusClaimed)
	b.RevisionFeedback = cleanFeedback
	b.DeadlineHeight = runtime.ChainHeight() + b.DeadlineBlocks

	chain.Emit(
		"RevisionRequested",
		"id", strconv.FormatUint(id, 10),
		"sponsor", string(caller),
		"new_deadline_height", strconv.FormatInt(b.DeadlineHeight, 10),
	)
}

// ApproveAndSettle releases the full ugnot escrow to the claimant, records a
// 1-5 quality rating, and updates on-chain reputation using CEI ordering.
func ApproveAndSettle(cur realm, id uint64, rating uint8, reviewNote string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: bounty is not awaiting approval")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may approve and settle")
	}

	validRating := hearthcore.ValidateRating(rating)
	cleanNote := hearthcore.ValidateText("reviewNote", reviewNote, 0, hearthcore.MaxNoteLen)

	payout := b.EscrowUgnot
	recipient := b.Claimant
	height := runtime.ChainHeight()

	// Effects before external bank interaction (CEI).
	b.EscrowUgnot = 0
	b.PayoutUgnot = payout
	b.Rating = validRating
	b.ReviewNote = cleanNote
	b.SettledHeight = height
	transitionStatus(b, hearthcore.StatusSettled)
	totalEscrowUgnot -= payout
	totalSettledUgnot += payout

	hp := getOrCreateProfile(recipient, height)
	hp.SettledCount++
	hp.EarnedUgnot += payout
	hp.RatingSum += uint64(validRating)
	hp.RatingCount++

	sp := getOrCreateProfile(b.Sponsor, height)
	sp.SponsoredSettled++

	// Interaction: send escrowed ugnot from realm address to claimant.
	if payout > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), recipient, chain.Coins{{Denom: hearthcore.Denom, Amount: payout}})
	}

	chain.Emit(
		"BountySettled",
		"id", strconv.FormatUint(id, 10),
		"sponsor", string(b.Sponsor),
		"claimant", string(recipient),
		"payout_ugnot", strconv.FormatInt(payout, 10),
		"rating", strconv.Itoa(int(validRating)),
	)
}

// CancelBounty refunds escrowed ugnot to the sponsor. Only permitted while the
// bounty is Open so sponsors cannot withdraw funds from an active claim.
func CancelBounty(cur realm, id uint64) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusOpen {
		panic("hearthbounty: only open bounties can be cancelled")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor {
		panic("hearthbounty: only the sponsor may cancel")
	}

	refund := b.EscrowUgnot
	b.EscrowUgnot = 0
	b.RefundUgnot = refund
	transitionStatus(b, hearthcore.StatusCancelled)
	totalEscrowUgnot -= refund
	totalRefundUgnot += refund

	if refund > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), b.Sponsor, chain.Coins{{Denom: hearthcore.Denom, Amount: refund}})
	}

	chain.Emit(
		"BountyCancelled",
		"id", strconv.FormatUint(id, 10),
		"sponsor", string(b.Sponsor),
		"refund_ugnot", strconv.FormatInt(refund, 10),
	)
}

// OpenDispute escalates a submitted bounty to arbiter review. Either the
// sponsor or the active claimant may open a dispute.
func OpenDispute(cur realm, id uint64, reason string) {
	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusSubmitted {
		panic("hearthbounty: disputes can only be opened on submitted bounties")
	}

	caller := cur.Previous().Address()
	if caller != b.Sponsor && caller != b.Claimant {
		panic("hearthbounty: only sponsor or claimant may open a dispute")
	}

	cleanReason := hearthcore.ValidateText("reason", reason, 6, hearthcore.MaxNoteLen)
	transitionStatus(b, hearthcore.StatusDisputed)
	b.DisputeReason = cleanReason
	b.DisputeOpenedBy = caller

	chain.Emit(
		"DisputeOpened",
		"id", strconv.FormatUint(id, 10),
		"opened_by", string(caller),
		"reason", cleanReason,
	)
}

// ResolveDispute settles a disputed bounty using deterministic basis-point math
// (hunterBps in 0..10000). The remainder is refunded atomically to the sponsor.
func ResolveDispute(cur realm, id uint64, hunterBps uint64, resolution string) {
	caller := cur.Previous().Address()
	if caller != arbiter {
		panic("hearthbounty: only the arbiter may resolve disputes")
	}

	b, ok := getBountyRecord(id)
	if !ok {
		panic("hearthbounty: bounty not found")
	}
	if b.Status != hearthcore.StatusDisputed {
		panic("hearthbounty: bounty is not disputed")
	}

	cleanResolution := hearthcore.ValidateText("resolution", resolution, 4, hearthcore.MaxNoteLen)
	escrow := b.EscrowUgnot
	hunterShare, sponsorShare := hearthcore.ComputeSplit(escrow, hunterBps)
	height := runtime.ChainHeight()

	// Effects before interactions (CEI).
	b.EscrowUgnot = 0
	b.PayoutUgnot = hunterShare
	b.RefundUgnot = sponsorShare
	b.ReviewNote = "[Arbiter Resolution] " + cleanResolution
	b.SettledHeight = height
	transitionStatus(b, hearthcore.StatusSettled)
	totalEscrowUgnot -= escrow
	totalSettledUgnot += hunterShare
	totalRefundUgnot += sponsorShare

	if hunterShare > 0 {
		hp := getOrCreateProfile(b.Claimant, height)
		hp.SettledCount++
		hp.EarnedUgnot += hunterShare
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if hunterShare > 0 {
		bnk.SendCoins(cur.Address(), b.Claimant, chain.Coins{{Denom: hearthcore.Denom, Amount: hunterShare}})
	}
	if sponsorShare > 0 {
		bnk.SendCoins(cur.Address(), b.Sponsor, chain.Coins{{Denom: hearthcore.Denom, Amount: sponsorShare}})
	}

	chain.Emit(
		"DisputeResolved",
		"id", strconv.FormatUint(id, 10),
		"arbiter", string(caller),
		"hunter_bps", strconv.FormatUint(hunterBps, 10),
		"hunter_ugnot", strconv.FormatInt(hunterShare, 10),
		"sponsor_refund_ugnot", strconv.FormatInt(sponsorShare, 10),
	)
}

// requireSingleUgnotSend validates that the caller attached exclusively ugnot
// at or above minAmount so unsupported denominations cannot get trapped.
func requireSingleUgnotSend(minAmount int64) int64 {
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		panic("hearthbounty: must attach ugnot escrow coins")
	}
	if len(sent) != 1 || sent[0].Denom != hearthcore.Denom {
		panic("hearthbounty: only ugnot coins are accepted")
	}
	if sent[0].Amount < minAmount {
		panic("hearthbounty: attached ugnot is below minimum required amount")
	}
	return sent[0].Amount
}

func normalizeFilter(raw string) string {
	return strings.ToLower(strings.TrimSpace(raw))
}

package hearthbounty

import (
	"chain/runtime"
	"sort"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
)

// Arbiter returns the current dispute arbiter address.
func Arbiter() address {
	return arbiter
}

// GetStats returns an immutable snapshot of protocol counters and escrow totals.
func GetStats() BoardStats {
	return BoardStats{
		TotalBounties:     bounties.Size(),
		OpenCount:         openCount,
		ClaimedCount:      claimedCount,
		SubmittedCount:    submittedCount,
		DisputedCount:     disputedCount,
		SettledCount:      settledCount,
		CancelledCount:    cancelledCount,
		ProfileCount:      profiles.Size(),
		AgentCount:        agentCount,
		TotalEscrowUgnot:  totalEscrowUgnot,
		TotalSettledUgnot: totalSettledUgnot,
		TotalRefundUgnot:  totalRefundUgnot,
	}
}

// GetBounty returns a value copy of a single bounty by ID.
func GetBounty(id uint64) (BountyView, bool) {
	b, ok := getBountyRecord(id)
	if !ok {
		return BountyView{}, false
	}
	return toBountyView(b), true
}

// GetProfile returns a value copy of a builder or AI agent profile.
func GetProfile(addr address) (ProfileView, bool) {
	raw := profiles.Get(string(addr))
	if raw == nil {
		return ProfileView{}, false
	}
	return toProfileView(raw.(*profileRecord)), true
}

// ExportStatsJSON returns global protocol stats as deterministic JSON for MCP agents.
func ExportStatsJSON() string {
	s := GetStats()
	return hearthcore.NewJSONObject().
		Str("realm_path", realmWebBase).
		Str("arbiter", string(arbiter)).
		Int64("chain_height", runtime.ChainHeight()).
		Int64("total_bounties", int64(s.TotalBounties)).
		Int64("open_count", int64(s.OpenCount)).
		Int64("claimed_count", int64(s.ClaimedCount)).
		Int64("submitted_count", int64(s.SubmittedCount)).
		Int64("disputed_count", int64(s.DisputedCount)).
		Int64("settled_count", int64(s.SettledCount)).
		Int64("cancelled_count", int64(s.CancelledCount)).
		Int64("profile_count", int64(s.ProfileCount)).
		Int64("agent_count", int64(s.AgentCount)).
		Int64("total_escrow_ugnot", s.TotalEscrowUgnot).
		Int64("total_settled_ugnot", s.TotalSettledUgnot).
		Int64("total_refund_ugnot", s.TotalRefundUgnot).
		String()
}

// ExportBountyJSON returns a single bounty as deterministic JSON (or {"found":false}).
func ExportBountyJSON(id uint64) string {
	b, ok := getBountyRecord(id)
	if !ok {
		return `{"found":false}`
	}
	return encodeBountyJSON(b, true)
}

// ExportBountiesJSON lists bounties in reverse chronological order with optional
// status, category, and minimum reward filters for autonomous agent discovery.
func ExportBountiesJSON(statusFilter, categoryFilter string, minRewardUgnot int64, limit int) string {
	st := normalizeFilter(statusFilter)
	cat := normalizeFilter(categoryFilter)
	if limit <= 0 || limit > 100 {
		limit = 50
	}

	items := make([]string, 0)
	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		b := val.(*bountyRecord)
		if st != "" && string(b.Status) != st {
			return false
		}
		if cat != "" && string(b.Category) != cat {
			return false
		}
		reward := effectiveReward(b)
		if minRewardUgnot > 0 && reward < minRewardUgnot {
			return false
		}
		items = append(items, encodeBountyJSON(b, false))
		return len(items) >= limit
	})

	return hearthcore.NewJSONObject().
		Int64("chain_height", runtime.ChainHeight()).
		Int64("count", int64(len(items))).
		Raw("bounties", hearthcore.JoinJSONArray(items)).
		String()
}

// ExportLeaderboardJSON returns deterministically sorted builders & AI agents.
func ExportLeaderboardJSON(limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 25
	}
	ranked := rankedProfiles()
	if len(ranked) > limit {
		ranked = ranked[:limit]
	}

	items := make([]string, 0, len(ranked))
	for i, p := range ranked {
		items = append(items, encodeProfileJSON(p, i+1))
	}

	return hearthcore.NewJSONObject().
		Int64("count", int64(len(items))).
		Raw("leaderboard", hearthcore.JoinJSONArray(items)).
		String()
}

// ExportProfileJSON returns a single profile as deterministic JSON.
func ExportProfileJSON(addrStr string) string {
	raw := profiles.Get(addrStr)
	if raw == nil {
		return `{"found":false}`
	}
	p := raw.(*profileRecord)
	return encodeProfileJSON(p, 0)
}

func effectiveReward(b *bountyRecord) int64 {
	if b.EscrowUgnot > 0 {
		return b.EscrowUgnot
	}
	if b.PayoutUgnot > 0 {
		return b.PayoutUgnot
	}
	if b.RefundUgnot > 0 {
		return b.RefundUgnot
	}
	return b.InitialUgnot
}

func encodeBountyJSON(b *bountyRecord, includeFound bool) string {
	jb := hearthcore.NewJSONObject()
	if includeFound {
		jb.Bool("found", true)
	}
	jb.Uint64("id", b.ID).
		Str("title", b.Title).
		Str("spec", b.Spec).
		Str("category", string(b.Category)).
		Str("status", string(b.Status)).
		Str("sponsor", string(b.Sponsor)).
		Str("claimant", string(b.Claimant)).
		Str("claim_note", b.ClaimNote).
		Int64("escrow_ugnot", b.EscrowUgnot).
		Int64("initial_ugnot", b.InitialUgnot).
		Int64("payout_ugnot", b.PayoutUgnot).
		Int64("refund_ugnot", b.RefundUgnot).
		Str("reward_formatted", hearthcore.FormatGNOT(effectiveReward(b))).
		Uint64("top_up_count", b.TopUpCount).
		Int64("deadline_blocks", b.DeadlineBlocks).
		Int64("created_height", b.CreatedHeight).
		Int64("claimed_height", b.ClaimedHeight).
		Int64("deadline_height", b.DeadlineHeight).
		Int64("submitted_height", b.SubmittedHeight).
		Int64("settled_height", b.SettledHeight).
		Str("proof_url", b.ProofURL).
		Str("proof_digest", b.ProofDigest).
		Str("proof_summary", b.ProofSummary).
		Uint64("submission_count", b.SubmissionCount).
		Str("revision_feedback", b.RevisionFeedback).
		Uint64("rating", uint64(b.Rating)).
		Str("review_note", b.ReviewNote).
		Str("dispute_reason", b.DisputeReason).
		Str("dispute_opened_by", string(b.DisputeOpenedBy))
	return jb.String()
}

func encodeProfileJSON(p *profileRecord, rank int) string {
	tier := hearthcore.ComputeTier(p.SettledCount, p.EarnedUgnot, p.RatingSum, p.RatingCount)
	jb := hearthcore.NewJSONObject()
	if rank == 0 {
		jb.Bool("found", true)
	} else {
		jb.Int64("rank", int64(rank))
	}
	jb.Str("address", string(p.Address)).
		Str("handle", p.Handle).
		Str("bio", p.Bio).
		Str("skills", p.Skills).
		Str("agent_endpoint", p.AgentEndpoint).
		Bool("is_agent", p.IsAgent).
		Str("tier", string(tier)).
		Uint64("posted_count", p.PostedCount).
		Uint64("claimed_count", p.ClaimedCount).
		Uint64("settled_count", p.SettledCount).
		Uint64("sponsored_settled", p.SponsoredSettled).
		Int64("earned_ugnot", p.EarnedUgnot).
		Str("earned_formatted", hearthcore.FormatGNOT(p.EarnedUgnot)).
		Int64("sponsored_ugnot", p.SponsoredUgnot).
		Str("rating_formatted", hearthcore.FormatRating(p.RatingSum, p.RatingCount)).
		Uint64("rating_sum", p.RatingSum).
		Uint64("rating_count", p.RatingCount)
	return jb.String()
}

type profileRankSlice []*profileRecord

func (s profileRankSlice) Len() int { return len(s) }
func (s profileRankSlice) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}
func (s profileRankSlice) Less(i, j int) bool {
	a, b := s[i], s[j]
	if a.EarnedUgnot != b.EarnedUgnot {
		return a.EarnedUgnot > b.EarnedUgnot
	}
	if a.SettledCount != b.SettledCount {
		return a.SettledCount > b.SettledCount
	}
	if a.SponsoredUgnot != b.SponsoredUgnot {
		return a.SponsoredUgnot > b.SponsoredUgnot
	}
	return string(a.Address) < string(b.Address)
}

func rankedProfiles() []*profileRecord {
	list := make([]*profileRecord, 0, profiles.Size())
	profiles.Iterate("", "", func(_ string, val any) bool {
		list = append(list, val.(*profileRecord))
		return false
	})

	sort.Sort(profileRankSlice(list))
	return list
}

package hearthbounty

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1x582angdzrqadgv4382j6y7ju6fj5wll6yuuq4/hearthcore/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
)

func initRouter() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("category/{cat}", renderCategory)
	router.HandleFunc("bounty/{id}", renderBountyDetail)
	router.HandleFunc("post", renderPostPage)
	router.HandleFunc("leaderboard", renderLeaderboard)
	router.HandleFunc("profile/{addr}", renderProfilePage)
	router.HandleFunc("agents", renderAgentsHub)
	router.NotFoundHandler = renderNotFound
}

// Render serves the native gnoweb interactive interface and machine-readable
// Markdown views. Strictly read-only; all dynamic inputs are sanitized.
func Render(path string) string {
	return router.Render(path)
}

func safeInline(s string) string {
	return hearthcore.NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.InlineText(s)))
}

func safeCell(s string) string {
	return hearthcore.NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.TableCell(s)))
}

func safeBlock(s string) string {
	return hearthcore.NeutralizeGnoTags(hearthcore.EscapeMath(sanitize.Block(s)))
}

func safeURL(s string) string {
	return sanitize.URL(s)
}

func routeHref(sub string) string {
	if sub == "" {
		return realmWebBase
	}
	return realmWebBase + ":" + sub
}

func writeTopNav(b *strings.Builder, active string) {
	homeVar := "outline"
	if active == "home" {
		homeVar = "info"
	}
	postVar := "outline"
	if active == "post" {
		postVar = "success"
	}
	lbVar := "outline"
	if active == "leaderboard" {
		lbVar = "info"
	}
	agentVar := "outline"
	if active == "agents" {
		agentVar = "info"
	}

	b.WriteString(`<gno-button href="` + routeHref("") + `" label="Bounty Board" variant="` + homeVar + `" /> `)
	b.WriteString(`<gno-button href="` + routeHref("post") + `" label="+ Post Bounty" variant="` + postVar + `" /> `)
	b.WriteString(`<gno-button href="` + routeHref("leaderboard") + `" label="Guild Leaderboard" variant="` + lbVar + `" /> `)
	b.WriteString(`<gno-button href="` + routeHref("agents") + `" label="AI Agent MCP Hub" variant="` + agentVar + `" />` + "\n\n")
}

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	renderBoardView(res, "")
}

func renderCategory(res *mux.ResponseWriter, req *mux.Request) {
	rawCat := req.GetVar("cat")
	cat, ok := hearthcore.ParseCategory(rawCat)
	if !ok {
		renderNotFound(res, req)
		return
	}
	renderBoardView(res, string(cat))
}

func renderBoardView(res *mux.ResponseWriter, filterCat string) {
	var b strings.Builder
	s := GetStats()

	b.WriteString("# <gno-icon name=\"flame\" /> HearthBounty\n\n")
	writeTopNav(&b, "home")

	// Live deterministic on-chain SVG hero banner & status distribution bar.
	b.WriteString(hearthcore.RenderHeroBannerSVG(
		s.OpenCount,
		s.ClaimedCount,
		s.SubmittedCount,
		s.SettledCount,
		s.TotalEscrowUgnot,
		s.TotalSettledUgnot,
	))
	b.WriteString("\n\n")

	// 3-column KPI cards using gnoweb v1.8.0 native frames & columns.
	b.WriteString("<gno-columns>\n")
	b.WriteString("<gno-frame>\n")
	b.WriteString("### <gno-icon name=\"coins\" /> Active Escrow\n\n")
	b.WriteString("**" + hearthcore.FormatGNOT(s.TotalEscrowUgnot) + "** locked across **" +
		strconv.Itoa(s.OpenCount+s.ClaimedCount+s.SubmittedCount+s.DisputedCount) + "** active bounties.\n\n")
	b.WriteString("Settled all-time: **" + hearthcore.FormatGNOT(s.TotalSettledUgnot) + "**\n")
	b.WriteString("</gno-frame>\n")
	b.WriteString("<gno-columns-sep />\n")
	b.WriteString("<gno-frame>\n")
	b.WriteString("### <gno-icon name=\"trophy\" /> Guild Activity\n\n")
	b.WriteString("**" + strconv.Itoa(s.TotalBounties) + "** total quests · **" +
		strconv.Itoa(s.SettledCount) + "** settled · **" +
		strconv.Itoa(s.OpenCount) + "** open right now.\n\n")
	b.WriteString("Current block height: `" + strconv.FormatInt(runtime.ChainHeight(), 10) + "`\n")
	b.WriteString("</gno-frame>\n")
	b.WriteString("<gno-columns-sep />\n")
	b.WriteString("<gno-frame>\n")
	b.WriteString("### <gno-icon name=\"ai\" /> Builders & AI Agents\n\n")
	b.WriteString("**" + strconv.Itoa(s.ProfileCount) + "** guild profiles (**" +
		strconv.Itoa(s.AgentCount) + "** MCP AI agents).\n\n")
	b.WriteString("100% pure on-chain state + JSON `vm/qeval` surface.\n")
	b.WriteString("</gno-frame>\n")
	b.WriteString("</gno-columns>\n\n")

	// Category filter bar.
	b.WriteString("## <gno-icon name=\"filter\" /> Filter by Track\n\n")
	allVariant := "outline"
	if filterCat == "" {
		allVariant = "info"
	}
	b.WriteString(`<gno-button href="` + routeHref("") + `" label="All Tracks" variant="` + allVariant + `" /> `)
	for _, cat := range hearthcore.AllCategories() {
		v := "outline"
		if filterCat == string(cat) {
			v = "info"
		}
		b.WriteString(`<gno-button href="` + routeHref("category/"+string(cat)) + `" label="` + cat.Label() + `" variant="` + v + `" /> `)
	}
	b.WriteString("\n\n")

	// Bounty board table.
	if filterCat == "" {
		b.WriteString("## <gno-icon name=\"list\" /> Live Bounty Board\n\n")
	} else {
		cat, _ := hearthcore.ParseCategory(filterCat)
		b.WriteString("## <gno-icon name=\"" + cat.IconName() + "\" /> " + cat.Label() + " Bounties\n\n")
	}

	rows := 0
	var tbl strings.Builder
	tbl.WriteString("| ID | Bounty | Track | Status | Escrow / Payout | Sponsor | Hunter |\n")
	tbl.WriteString("|---:|---|---|---|---|---|---|\n")

	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		rec := val.(*bountyRecord)
		if filterCat != "" && string(rec.Category) != filterCat {
			return false
		}
		idStr := strconv.FormatUint(rec.ID, 10)
		titleLink := "[**" + safeCell(rec.Title) + "**](" + routeHref("bounty/"+idStr) + ")"
		catCell := "<gno-icon name=\"" + rec.Category.IconName() + "\" /> " + rec.Category.Label()
		stCell := "<gno-icon name=\"" + rec.Status.IconName() + "\" /> **" + rec.Status.Label() + "**"
		rewardCell := "**" + hearthcore.FormatGNOT(effectiveReward(rec)) + "**"
		sponsorCell := "[" + safeCell(displayHandle(rec.Sponsor)) + "](" + routeHref("profile/"+string(rec.Sponsor)) + ")"
		hunterCell := "_Unclaimed_"
		if rec.Claimant != "" {
			hunterCell = "[" + safeCell(displayHandle(rec.Claimant)) + "](" + routeHref("profile/"+string(rec.Claimant)) + ")"
		}

		tbl.WriteString("| `" + idStr + "` | " + titleLink + " | " + catCell + " | " + stCell + " | " + rewardCell + " | " + sponsorCell + " | " + hunterCell + " |\n")
		rows++
		return rows >= 40
	})

	if rows == 0 {
		b.WriteString("> [!INFO] No Bounties Posted Yet\n")
		b.WriteString("> Be the first to pin a micro-bounty to the hearth! Click **+ Post Bounty** above or call `PostBounty` via `gnokey` / `gnomcp` with attached `ugnot`.\n\n")
	} else {
		b.WriteString(tbl.String())
		b.WriteString("\n")
	}

	b.WriteString("> [!TIP] Built for Humans AND Autonomous Agents\n")
	b.WriteString("> Humans browse and transact directly inside `gnoweb` with Adena wallet forms. AI agents query `ExportBountiesJSON(\"open\", \"\", 0, 20)` via `vm/qeval` or connect `hearthbounty-mcp` alongside `gnomcp` to discover, claim, submit proofs, and settle bounties deterministically.\n")

	res.Write(b.String())
}

func renderBountyDetail(res *mux.ResponseWriter, req *mux.Request) {
	rawID := req.GetVar("id")
	id, err := strconv.ParseUint(rawID, 10, 64)
	if err != nil {
		renderNotFound(res, req)
		return
	}
	rec, ok := getBountyRecord(id)
	if !ok {
		renderNotFound(res, req)
		return
	}

	var b strings.Builder
	idStr := strconv.FormatUint(rec.ID, 10)

	b.WriteString("# <gno-icon name=\"" + rec.Category.IconName() + "\" /> Bounty #" + idStr + ": " + safeInline(rec.Title) + "\n\n")
	writeTopNav(&b, "home")

	// Visual lifecycle progress bar + escrow pill.
	b.WriteString(hearthcore.RenderLifecycleSVG(rec.Status, effectiveReward(rec)))
	b.WriteString("\n\n")

	// Metadata two-column layout.
	b.WriteString("<gno-columns>\n")
	b.WriteString("<gno-frame>\n")
	b.WriteString("### <gno-icon name=\"document\" /> Specification\n\n")
	b.WriteString(safeBlock(rec.Spec))
	b.WriteString("\n")
	b.WriteString("</gno-frame>\n")
	b.WriteString("<gno-columns-sep />\n")
	b.WriteString("<gno-frame>\n")
	b.WriteString("### <gno-icon name=\"coins\" /> Escrow & Participants\n\n")
	b.WriteString("- **Status:** <gno-icon name=\"" + rec.Status.IconName() + "\" /> **" + rec.Status.Label() + "**\n")
	b.WriteString("- **Track:** <gno-icon name=\"" + rec.Category.IconName() + "\" /> " + rec.Category.Label() + "\n")
	b.WriteString("- **Escrow Locked:** **" + hearthcore.FormatGNOT(rec.EscrowUgnot) + "** (`" + strconv.FormatInt(rec.EscrowUgnot, 10) + "ugnot`)\n")
	if rec.PayoutUgnot > 0 {
		b.WriteString("- **Settled Payout:** **" + hearthcore.FormatGNOT(rec.PayoutUgnot) + "**\n")
	}
	if rec.RefundUgnot > 0 {
		b.WriteString("- **Refunded:** **" + hearthcore.FormatGNOT(rec.RefundUgnot) + "**\n")
	}
	b.WriteString("- **Top-Ups:** " + strconv.FormatUint(rec.TopUpCount, 10) + "\n")
	b.WriteString("- **Sponsor:** [" + safeInline(displayHandle(rec.Sponsor)) + "](" + routeHref("profile/"+string(rec.Sponsor)) + ") (`" + string(rec.Sponsor) + "`)\n")
	if rec.Claimant != "" {
		b.WriteString("- **Claimant:** [" + safeInline(displayHandle(rec.Claimant)) + "](" + routeHref("profile/"+string(rec.Claimant)) + ") (`" + string(rec.Claimant) + "`)\n")
		b.WriteString("- **Claim Window Deadline:** Block `" + strconv.FormatInt(rec.DeadlineHeight, 10) + "` (now `" + strconv.FormatInt(runtime.ChainHeight(), 10) + "`)\n")
	} else {
		b.WriteString("- **Claimant:** _Open for builders & AI agents_\n")
		b.WriteString("- **Claim Window:** `" + strconv.FormatInt(rec.DeadlineBlocks, 10) + "` blocks after claim\n")
	}
	b.WriteString("</gno-frame>\n")
	b.WriteString("</gno-columns>\n\n")

	// Claim note, revision feedback, proof & review sections.
	if rec.ClaimNote != "" {
		b.WriteString("> [!NOTE] Claimant Execution Plan\n")
		b.WriteString("> " + safeInline(rec.ClaimNote) + "\n\n")
	}

	if rec.RevisionFeedback != "" {
		b.WriteString("> [!WARNING] Sponsor Revision Request\n")
		b.WriteString("> " + safeInline(rec.RevisionFeedback) + "\n\n")
	}

	if rec.ProofURL != "" {
		b.WriteString("## <gno-icon name=\"check-circle\" /> Submitted Proof of Work\n\n")
		b.WriteString("<gno-frame>\n")
		b.WriteString("- **Deliverable Link:** [" + safeInline(rec.ProofURL) + "](" + safeURL(rec.ProofURL) + ")\n")
		b.WriteString("- **Content Digest:** `" + safeInline(rec.ProofDigest) + "`\n")
		b.WriteString("- **Submitted at Block:** `" + strconv.FormatInt(rec.SubmittedHeight, 10) + "` (attempt #" + strconv.FormatUint(rec.SubmissionCount, 10) + ")\n\n")
		b.WriteString("**Summary:** " + safeBlock(rec.ProofSummary) + "\n")
		b.WriteString("</gno-frame>\n\n")
	}

	if rec.DisputeReason != "" {
		b.WriteString("> [!CAUTION] Dispute Raised by `" + string(rec.DisputeOpenedBy) + "`\n")
		b.WriteString("> " + safeInline(rec.DisputeReason) + "\n\n")
	}

	if rec.Status == hearthcore.StatusSettled {
		b.WriteString("> [!SUCCESS] Bounty Settled at Block `" + strconv.FormatInt(rec.SettledHeight, 10) + "`\n")
		if rec.Rating > 0 {
			b.WriteString("> **Quality Rating:** " + strconv.Itoa(int(rec.Rating)) + " / 5")
			if rec.ReviewNote != "" {
				b.WriteString(" — " + safeInline(rec.ReviewNote))
			}
			b.WriteString("\n\n")
		} else if rec.ReviewNote != "" {
			b.WriteString("> " + safeInline(rec.ReviewNote) + "\n\n")
		}
	}

	// Contextual interactive gnoweb transaction forms + txlink quick actions.
	b.WriteString("## <gno-icon name=\"terminal\" /> Interactive On-Chain Actions\n\n")
	writeContextualActions(&b, rec)

	res.Write(b.String())
}

func writeContextualActions(b *strings.Builder, rec *bountyRecord) {
	idStr := strconv.FormatUint(rec.ID, 10)

	switch rec.Status {
	case hearthcore.StatusOpen:
		topUpURL := txlink.NewLink("TopUpBounty").AddArgs("id", idStr).SetSend("500000ugnot").URL()
		cancelURL := txlink.NewLink("CancelBounty").AddArgs("id", idStr).URL()

		b.WriteString(`<gno-button href="` + topUpURL + `" label="Crowd-Fund +0.50 GNOT" variant="success" /> `)
		b.WriteString(`<gno-button href="` + cancelURL + `" label="Cancel & Refund (Sponsor)" variant="warning" />` + "\n\n")

		b.WriteString("### Claim This Bounty\n\n")
		b.WriteString("<gno-form exec=\"ClaimBounty\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"agentNote\" placeholder=\"Execution plan, repo link, or MCP agent capability note\" rows=\"3\" />\n")
		b.WriteString("</gno-form>\n\n")

	case hearthcore.StatusClaimed:
		topUpURL := txlink.NewLink("TopUpBounty").AddArgs("id", idStr).SetSend("500000ugnot").URL()
		releaseURL := txlink.NewLink("ReleaseExpiredClaim").AddArgs("id", idStr).URL()

		b.WriteString(`<gno-button href="` + topUpURL + `" label="Crowd-Fund +0.50 GNOT" variant="success" /> `)
		b.WriteString(`<gno-button href="` + releaseURL + `" label="Release Claim (Claimant / Post-Deadline)" variant="outline" />` + "\n\n")

		b.WriteString("### Submit Deliverable Proof (Claimant Only)\n\n")
		b.WriteString("<gno-form exec=\"SubmitProof\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-input name=\"proofURL\" type=\"text\" placeholder=\"Deliverable URL (https://... or ipfs://...)\" required=\"true\" />\n")
		b.WriteString("<gno-input name=\"proofDigest\" type=\"text\" placeholder=\"SHA-256 commit or artifact digest\" required=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"summary\" placeholder=\"Concise summary of test results and verification steps\" rows=\"4\" required=\"true\" />\n")
		b.WriteString("</gno-form>\n\n")

	case hearthcore.StatusSubmitted:
		b.WriteString("<gno-columns>\n")
		b.WriteString("<gno-frame>\n")
		b.WriteString("### Approve & Release Escrow (Sponsor)\n\n")
		b.WriteString("<gno-form exec=\"ApproveAndSettle\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-input name=\"rating\" type=\"number\" placeholder=\"Quality Rating (1-5)\" value=\"5\" required=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"reviewNote\" placeholder=\"Short review for the hunter's on-chain reputation\" rows=\"3\" />\n")
		b.WriteString("</gno-form>\n")
		b.WriteString("</gno-frame>\n")
		b.WriteString("<gno-columns-sep />\n")
		b.WriteString("<gno-frame>\n")
		b.WriteString("### Request Revision (Sponsor)\n\n")
		b.WriteString("<gno-form exec=\"RequestRevision\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"feedback\" placeholder=\"Specific changes required before approval\" rows=\"3\" required=\"true\" />\n")
		b.WriteString("</gno-form>\n")
		b.WriteString("</gno-frame>\n")
		b.WriteString("</gno-columns>\n\n")

		b.WriteString("### Escalate to Arbiter Dispute (Sponsor or Claimant)\n\n")
		b.WriteString("<gno-form exec=\"OpenDispute\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"reason\" placeholder=\"Evidence and rationale for arbiter split decision\" rows=\"3\" required=\"true\" />\n")
		b.WriteString("</gno-form>\n\n")

	case hearthcore.StatusDisputed:
		b.WriteString("### Arbiter Split Resolution (`" + string(arbiter) + "`)\n\n")
		b.WriteString("<gno-form exec=\"ResolveDispute\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" placeholder=\"Bounty ID\" value=\"" + idStr + "\" readonly=\"true\" />\n")
		b.WriteString("<gno-input name=\"hunterBps\" type=\"number\" placeholder=\"Hunter Share in Basis Points (0-10000)\" value=\"5000\" required=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"resolution\" placeholder=\"Arbiter findings and payout justification\" rows=\"3\" required=\"true\" />\n")
		b.WriteString("</gno-form>\n\n")

	default:
		b.WriteString("> [!INFO] Finalized State\n")
		b.WriteString("> This bounty has reached a terminal state (**" + rec.Status.Label() + "**) with zero remaining escrow locked.\n\n")
	}
}

func renderPostPage(res *mux.ResponseWriter, req *mux.Request) {
	var b strings.Builder

	b.WriteString("# <gno-icon name=\"plus\" /> Pin a New Micro-Bounty\n\n")
