// ----------------------------------------------------------------- helpers

func phaseBadge(ph string) string {
	switch ph {
	case PhaseOpen:
		return "**open** — sealing"
	case PhaseReveal:
		return "**reveal** — secrets being opened"
	case PhaseDrawable:
		return "**drawable** — waiting for a draw"
	case PhaseDrawn:
		return "**drawn**"
	case PhaseCancelled:
		return "cancelled"
	}
	return ph
}

func phaseTick(active bool) string {
	if active {
		return "←"
	}
	return ""
}

func closeLine(e *Event, now int64) string {
	switch e.phase(now) {
	case PhaseOpen:
		return "in " + left(e.ClosesAt, now)
	case PhaseReveal:
		return "closed " + left(now, e.ClosesAt) + " ago"
	case PhaseDrawable:
		return "closed " + left(now, e.ClosesAt) + " ago"
	case PhaseDrawn:
		return "drawn " + left(now, e.DrawnAt) + " ago"
	case PhaseCancelled:
		return "cancelled"
	}
	return ""
}

// left renders a positive duration in seconds as "2d 3h", "4h 12m", "3m 40s".
func left(until int64, from int64) string {
	d := until - from
	if d < 0 {
		d = 0
	}
	if d >= 86400 {
		return strconv.FormatInt(d/86400, 10) + "d " + strconv.FormatInt((d%86400)/3600, 10) + "h"
	}
	if d >= 3600 {
		return strconv.FormatInt(d/3600, 10) + "h " + strconv.FormatInt((d%3600)/60, 10) + "m"
	}
	if d >= 60 {
		return strconv.FormatInt(d/60, 10) + "m " + strconv.FormatInt(d%60, 10) + "s"
	}
	return strconv.FormatInt(d, 10) + "s"
}

// stamp renders a unix second in both UTC and KST, the two clocks this board's
// audience reads.
func stamp(unix int64) string {
	t := time.Unix(unix, 0).UTC()
	k := time.Unix(unix+9*3600, 0).UTC()
	return t.Format("2006-01-02 15:04") + " / " + k.Format("01-02 15:04") + " KST"
}

func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-6:]
}

// cell keeps a free-text field from breaking a markdown table.
func cell(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '|' {
			out += "\\|"
		} else if c == '\n' || c == '\r' {
			out += " "
		} else {
			out += string(c)
		}
	}
	return out
}

func quoteList(items []string) string {
	out := ""
	for i := 0; i < len(items); i++ {
		if i > 0 {
			out += ", "
		}
		out += "\"" + items[i] + "\""
	}
	return out
}

func parseUint(s string) (uint64, bool) {
	if s == "" {
		return 0, false
	}
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

package fairness

// Deterministic draw: a seed-driven byte stream and a weighted, multi-winner
// sample taken from it without replacement.
//
// Everything here is a pure function of its inputs, so the same seed over the
// same roster gives the same winners wherever it is recomputed — in a realm,
// in a test, or in a verifier script off chain.

import (
	"errors"
	"strconv"
)

// maxUint64 is 2^64-1.
const maxUint64 uint64 = 1<<64 - 1

// Ticket is one entry in a draw.
//
// ID is the entrant's stable identity — FairDrop uses the bech32 address
// string, so the roster is ordered and deduplicated by address. Commit is the
// seal, Secret the revealed preimage (empty until reveal) and Rank 0 until the
// draw, then 1..k for winners. The package only reads ID, Weight and Commit;
// Secret and Rank are carried so a realm can keep one record per ticket.
type Ticket struct {
	ID     string
	Weight uint64
	Commit string
	Secret string
	Rank   int
}

// Insert adds t to a roster kept in canonical (ascending ID) order and refuses
// an ID that is already present. One call therefore enforces both rules a
// draw depends on: a single ticket per entrant, and the fixed ordering the
// seed fold and the draw walk over.
//
// The returned slice is a new slice; the caller must keep it.
func Insert(roster []Ticket, t Ticket) ([]Ticket, error) {
	if t.ID == "" {
		return roster, errors.New("fairness: empty entrant id")
	}
	if t.Weight == 0 {
		return roster, errors.New("fairness: weight must be positive")
	}

	n := len(roster)
	lo, hi := 0, n
	for lo < hi {
		mid := (lo + hi) / 2
		if roster[mid].ID < t.ID {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo < n && roster[lo].ID == t.ID {
		return roster, errors.New("fairness: entrant already holds a ticket")
	}

	out := make([]Ticket, n+1)
	for i := 0; i < lo; i++ {
		out[i] = roster[i]
	}
	out[lo] = t
	for i := lo; i < n; i++ {
		out[i+1] = roster[i]
	}
	return out, nil
}

// Find returns the index of the ticket held by id, or -1.
func Find(roster []Ticket, id string) int {
	lo, hi := 0, len(roster)
	for lo < hi {
		mid := (lo + hi) / 2
		if roster[mid].ID < id {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo < len(roster) && roster[lo].ID == id {
		return lo
	}
	return -1
}

// Stream is a deterministic byte stream: SHA-256 in counter mode over the
// seed. It exists so a draw needs no randomness from the chain, which is what
// makes the result reproducible by anyone holding the seed.
type Stream struct {
	seed string
	ctr  uint64
	pool []byte
	pos  int
}

// NewStream starts a stream at seed.
func NewStream(seed string) *Stream {
	return &Stream{seed: seed}
}

func (s *Stream) refill() {
	sum := sha256Sum(s.seed + "|" + strconv.FormatUint(s.ctr, 10))
	s.ctr++
	s.pool = sum
	s.pos = 0
}

// Uint64 returns the next 8 stream bytes as a big-endian unsigned integer.
func (s *Stream) Uint64() uint64 {
	if s.pool == nil || s.pos+8 > len(s.pool) {
		s.refill()
	}
	var v uint64
	for i := 0; i < 8; i++ {
		v = (v << 8) | uint64(s.pool[s.pos+i])
	}
	s.pos += 8
	return v
}

// Below returns a uniform integer in [0, n) by rejection sampling, so no
// residue is favoured by the modulo. It panics on n == 0.
func (s *Stream) Below(n uint64) uint64 {
	if n == 0 {
		panic("fairness: Below(0)")
	}
	limit := (maxUint64 / n) * n
	for {
		v := s.Uint64()
		if v < limit {
			return v % n
		}
	}
}

// Draw samples up to k distinct tickets from roster, without replacement,
// with probability proportional to Weight, and returns their IDs in the order
// they were drawn (index 0 is rank 1). Zero-weight tickets are never drawn.
//
// The order of roster must be canonical (as Insert maintains it), because the
// stream walks the roster in that order.
func Draw(seed string, roster []Ticket, k int) []string {
	if k <= 0 || len(roster) == 0 {
		return []string{}
	}
	if k > len(roster) {
		k = len(roster)
	}

	// Work on a copy so the caller's roster (realm state) is untouched.
	pool := make([]Ticket, len(roster))
	for i := 0; i < len(roster); i++ {
		pool[i] = roster[i]
	}

	s := NewStream(seed)
	winners := make([]string, 0, k)
	for len(winners) < k {
		var total uint64
		for i := 0; i < len(pool); i++ {
			w := pool[i].Weight
			if w > 0 && total > maxUint64-w {
				panic("fairness: total weight overflows uint64")
			}
			total += w
		}
		if total == 0 {
			break
		}

		pick := s.Below(total)
		at := -1
		var acc uint64
		for i := 0; i < len(pool); i++ {
			if pool[i].Weight == 0 {
				continue
			}
			acc += pool[i].Weight
			if pick < acc {
				at = i
				break
			}
		}
		if at < 0 {
			// Unreachable while total > 0, kept as a hard stop rather than a
			// silent wrong pick.
			panic("fairness: weighted pick fell through")
		}

		winners = append(winners, pool[at].ID)

		kept := make([]Ticket, 0, len(pool)-1)
		for i := 0; i < len(pool); i++ {
			if i != at {
				kept = append(kept, pool[i])
			}
		}
		pool = kept
	}
	return winners
}

// TotalWeight sums the weights of a roster, panicking rather than wrapping.
func TotalWeight(roster []Ticket) uint64 {
	var total uint64
	for i := 0; i < len(roster); i++ {
		w := roster[i].Weight
		if w > 0 && total > maxUint64-w {
			panic("fairness: total weight overflows uint64")
		}
		total += w
	}
	return total
}

package fairness

// FairDrop sealed-entry primitives: commit–reveal sealing and seed folding.
//
// A draw is fair when nobody — the organizer included — can steer it.
// FairDrop gets there in three steps:
//
//  1. While entries are open, an entrant publishes only a seal: the SHA-256
//     of a secret they generated locally, bound to the entrant id, the event
//     domain (chain + event id) and the entrant's ticket weight.
//  2. When entries close, entrants reveal their secrets. A reveal is accepted
//     only when it re-hashes to the seal already on chain, so nobody can swap
//     their value after seeing the others.
//  3. The seed is the SHA-256 fold of every accepted reveal in canonical
//     (ascending entrant id) order. Whoever folds the same on-chain reveals
//     gets the same seed, and Draw turns that seed into winners
//     deterministically.
//
// What this does not solve, stated plainly: an entrant who never reveals is
// dropped from the draw (their ticket does not count either way), and the
// choice to withhold shifts which leaves the seed folds over. A revealed
// secret cannot be changed, so withholding only ever removes the withholder's
// own chance — it cannot pick someone else's winner. Callers should treat a
// missed reveal as a forfeit and say so in their UI.

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

const (
	// DigestHexLen is the length of a hex-encoded SHA-256 digest.
	DigestHexLen = 64

	// MinSecretLen is the shortest secret a reveal may carry. Shorter secrets
	// are guessable from the public seal and would let a watcher brute-force
	// an entrant's reveal before it lands.
	MinSecretLen = 16

	// MaxSecretLen bounds how much a single reveal may store on chain.
	MaxSecretLen = 256

	// SealDomain is the domain-separation tag of the sealing format.
	SealDomain = "fairdrop/seal/v1"

	// SeedDomain is the domain-separation tag of the seed fold.
	SeedDomain = "fairdrop/seed/v1"
)

// sha256Sum returns the raw 32-byte digest of s.
func sha256Sum(s string) []byte {
	sum := sha256.Sum256([]byte(s))
	return sum[:]
}

func hashHex(s string) string {
	return hex.EncodeToString(sha256Sum(s))
}

// Canonical is the exact string a seal commits to. Binding the entrant id,
// the domain (chain + event) and the weight means a seal cannot be replayed
// in another event or on another chain, cannot be claimed by another entrant,
// and cannot be reused at a different weight.
func Canonical(domain string, entrant string, weight int64, secret string) string {
	return SealDomain + "|" + domain + "|" + entrant + "|" + strconv.FormatInt(weight, 10) + "|" + secret
}

// Digest is the seal of one entry: hex SHA-256 over Canonical.
func Digest(domain string, entrant string, weight int64, secret string) string {
	return hashHex(Canonical(domain, entrant, weight, secret))
}

// VerifySeal reports whether secret opens commit for this entrant, weight and
// domain. Input is normalised (trimmed, lowercased) so a wallet or a human
// pasting an upper-case digest is not turned away.
func VerifySeal(commit string, domain string, entrant string, weight int64, secret string) bool {
	return strings.ToLower(strings.TrimSpace(commit)) == Digest(domain, entrant, weight, secret)
}

// IsDigest reports whether s is a well-formed lower-case hex SHA-256 digest.
func IsDigest(s string) bool {
	if len(s) != DigestHexLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') {
			continue
		}
		return false
	}
	return true
}

// NormalizeDigest returns the canonical form of a seal as submitted.
func NormalizeDigest(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

// ValidSecret reports whether s may be used as a reveal secret: printable
// ASCII without spaces, within the accepted length bounds.
func ValidSecret(s string) bool {
	n := len(s)
	if n < MinSecretLen || n > MaxSecretLen {
		return false
	}
	for i := 0; i < n; i++ {
		if s[i] < 0x21 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

// Leaf is one input of the seed fold: the seal followed by the secret that
// opened it. Leaves are folded in canonical entrant order.
func Leaf(commit string, secret string) string {
	return NormalizeDigest(commit) + ":" + secret
}

// Seed folds the revealed leaves into the draw seed. The domain, chain id and
// event id are part of the fold, so identical reveals in two events give
// different seeds and no seed can be lifted from one event to another.
func Seed(domain string, chainID string, eventID uint64, leaves []string) string {
	b := SeedDomain + "|" + domain + "|" + chainID + "|" + strconv.FormatUint(eventID, 10) + "|"
	for i := 0; i < len(leaves); i++ {
		b += leaves[i] + "|"
	}
	return hashHex(b)
}

package fairdrop

// FairDrop — a commit–reveal raffle board for gno.land.
//
// An organizer opens a draw with a prize and a number of winners. Entrants
// seal a ticket by submitting only a hash of a secret they generated locally;
// once entries close they reveal the secret, the realm re-hashes it against
// the seal, and when the reveal window ends anyone can trigger the draw. The
// seed is folded from the revealed secrets in address order, so every winner
// can be recomputed from public on-chain data — see Render("event/<id>/verify").
//
// The pure mechanics live in gno.land/p/fairdrop/fairness and are imported
// here; this realm owns the lifecycle, the storage and the pages.

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/fairness"
)

const (
	// RealmPath is this realm's own path and must equal the module line in
	// gnomod.toml (scripts/check.sh verifies that). It is part of every seal's
	// domain, so a seal made for this board cannot be replayed against another.
	RealmPath = "gno.land/r/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/fairdrop"

	// PackagePath is the reusable engine this realm imports.
	PackagePath = "gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/fairness"

	PhaseOpen      = "open"      // entries are being sealed
	PhaseReveal    = "reveal"    // entries closed, secrets being revealed
	PhaseDrawable  = "drawable"  // reveal window over, waiting for Draw
	PhaseDrawn     = "drawn"     // winners recorded
	PhaseCancelled = "cancelled" // voided by the organizer before entries closed

	// MaxSlots caps winners per event so a draw stays cheap to compute.
	MaxSlots = 100
	// MaxWeightCap caps organizer-granted ticket weight per address.
	MaxWeightCap = 100
	// MinWindowSeconds is the shortest window an event may open or reveal for.
	MinWindowSeconds = 30
	// MaxWindowSeconds is the longest window (30 days).
	MaxWindowSeconds = 30 * 24 * 60 * 60

	MaxTitleLen = 80
	MaxPrizeLen = 240
)

// Event is one draw.
type Event struct {
	ID           uint64
	Creator      address
	Title        string
	Prize        string
	Slots        int
	MaxWeight    uint64
	OpensAt      int64
	ClosesAt     int64
	RevealEndsAt int64

	// Roster holds the sealed tickets in canonical (ascending address) order;
	// fairness.Insert maintains that order and refuses a second ticket per
	// address. Secrets are filled in by Reveal and are public by design — they
	// are what makes the seed checkable.
	Roster []fairness.Ticket

	// vouches are organizer-granted ticket weights, address string -> weight.
	// A voucher must land before that address seals its ticket.
	vouches map[string]uint64

	Seed        string
	DrawnAt     int64
	DrawnHeight int64
	Cancelled   bool
}

var (
	events = []*Event{}
	byID   = map[uint64]*Event{}
	nextID uint64
)

// ---------------------------------------------------------------- lifecycle

// Create opens a draw and returns its id. The organizer pays nothing: FairDrop
// never holds funds, it only records the draw.
func Create(cur realm, title string, prize string, slots int, maxWeight int, regSeconds int, revealSeconds int) uint64 {
	runtime.AssertOriginCall()
	creator := unsafe.OriginCaller()

	title = trimSpace(title)
	prize = trimSpace(prize)
	require(title != "", "title is required")
	require(len(title) <= MaxTitleLen, "title is too long (max "+strconv.Itoa(MaxTitleLen)+" bytes)")
	require(prize != "", "prize is required")
	require(len(prize) <= MaxPrizeLen, "prize is too long (max "+strconv.Itoa(MaxPrizeLen)+" bytes)")
	require(slots >= 1 && slots <= MaxSlots, "winners must be between 1 and "+strconv.Itoa(MaxSlots))
	require(maxWeight >= 1 && maxWeight <= MaxWeightCap, "max weight must be between 1 and "+strconv.Itoa(MaxWeightCap))
	require(regSeconds >= MinWindowSeconds && regSeconds <= MaxWindowSeconds,
		"entry window must be between "+strconv.Itoa(MinWindowSeconds)+"s and "+strconv.Itoa(MaxWindowSeconds)+"s")
	require(revealSeconds >= MinWindowSeconds && revealSeconds <= MaxWindowSeconds,
		"reveal window must be between "+strconv.Itoa(MinWindowSeconds)+"s and "+strconv.Itoa(MaxWindowSeconds)+"s")

	now := time.Now().Unix()
	nextID++
	e := &Event{
		ID:           nextID,
		Creator:      creator,
		Title:        title,
		Prize:        prize,
		Slots:        slots,
		MaxWeight:    uint64(maxWeight),
		OpensAt:      now,
		ClosesAt:     now + int64(regSeconds),
		RevealEndsAt: now + int64(regSeconds) + int64(revealSeconds),
		Roster:       []fairness.Ticket{},
		vouches:      map[string]uint64{},
	}
	events = append(events, e)
	byID[e.ID] = e

	chain.Emit("EventCreated", "id", uitoa(e.ID), "creator", creator.String(), "slots", strconv.Itoa(slots))
	println("FairDrop event #" + uitoa(e.ID) + " opened: " + title)
	return e.ID
}

// Vouch grants an address extra ticket weight before it seals its ticket. One
// ticket per address is the floor; a vouch is how an organizer recognises a
// member who should carry more weight (a role holder, an allowlisted guest).
// Weight cannot be granted after the address has sealed, because the sealed
// digest commits to the weight.
func Vouch(cur realm, eventID uint64, who string, weight int) {
	runtime.AssertOriginCall()
	caller := unsafe.OriginCaller()
	e := mustEvent(eventID)

	require(!e.Cancelled, "event is cancelled")
	require(e.phase(nowUnix()) == PhaseOpen, "event is not open for entries")
	require(caller == e.Creator, "only the organizer can vouch")

	id := normalizeAddress(who)
	require(id != "", "address is required")
	require(weight >= 1 && uint64(weight) <= e.MaxWeight, "weight must be between 1 and "+uitoa(e.MaxWeight))
	require(fairness.Find(e.Roster, id) < 0, "address already sealed a ticket; weight is now fixed")

	e.vouches[id] = uint64(weight)
	chain.Emit("Vouched", "id", uitoa(e.ID), "who", id, "weight", strconv.Itoa(weight))
}

// Register seals a ticket: commit is the hex SHA-256 of the entrant's secret
// bound to their address, this event and their weight. Weight must be 1 unless
// the organizer vouched for more.
func Register(cur realm, eventID uint64, commit string, weight int) {
	runtime.AssertOriginCall()
	caller := unsafe.OriginCaller()
	e := mustEvent(eventID)

	require(!e.Cancelled, "event is cancelled")
	require(e.phase(nowUnix()) == PhaseOpen, "entries are closed")

	id := caller.String()
	commit = fairness.NormalizeDigest(commit)
	require(fairness.IsDigest(commit), "commit must be a 64-character hex sha256 digest")
	require(weight >= 1, "weight must be at least 1")

	w := uint64(weight)
	require(w <= e.MaxWeight, "weight exceeds this event's cap of "+uitoa(e.MaxWeight))
	if v, ok := e.vouches[id]; ok {
		require(w <= v, "weight exceeds the organizer's vouch of "+uitoa(v))
	} else {
		require(w == 1, "one ticket per address unless the organizer vouched for more")
	}

	roster, err := fairness.Insert(e.Roster, fairness.Ticket{
		ID:     id,
		Weight: w,
		Commit: commit,
	})
	require(err == nil, errString(err))
	e.Roster = roster

	chain.Emit("TicketSealed", "id", uitoa(e.ID), "entrant", id, "weight", uitoa(w))
	println("ticket sealed for event #" + uitoa(e.ID) + " by " + id)
}

// Reveal opens a seal. It is accepted only inside the reveal window and only
// when the secret re-hashes to the seal already on chain.
func Reveal(cur realm, eventID uint64, secret string) {
	runtime.AssertOriginCall()
	caller := unsafe.OriginCaller()
	e := mustEvent(eventID)

	require(!e.Cancelled, "event is cancelled")
	require(e.phase(nowUnix()) == PhaseReveal, "reveal window is not open")

	idx := fairness.Find(e.Roster, caller.String())
	require(idx >= 0, "no sealed ticket for this address")

	t := e.Roster[idx]
	require(t.Secret == "", "ticket already revealed")
	require(fairness.ValidSecret(secret), "secret must be printable ASCII, "+
		strconv.Itoa(fairness.MinSecretLen)+"-"+strconv.Itoa(fairness.MaxSecretLen)+" bytes")

	require(fairness.VerifySeal(t.Commit, e.Domain(), t.ID, int64(t.Weight), secret),
		"secret does not open this ticket's seal")

	e.Roster[idx].Secret = secret
	chain.Emit("TicketRevealed", "id", uitoa(e.ID), "entrant", t.ID)
	println("ticket revealed for event #" + uitoa(e.ID) + " by " + t.ID)
}

// Draw records the winners. It is permissionless on purpose: once the reveal
// window is over the result is already determined by public data, so anyone —
// entrant, organizer or passer-by — may pay the gas to write it down.
func Draw(cur realm, eventID uint64) {
	runtime.AssertOriginCall()
	e := mustEvent(eventID)

	require(!e.Cancelled, "event is cancelled")
	require(e.Seed == "", "event already drawn")

	now := nowUnix()
	ph := e.phase(now)
	// The result is fixed as soon as everyone who sealed has revealed; waiting
	// for the deadline then would only delay a foregone conclusion.
	allRevealed := len(e.Roster) > 0 && revealedCount(e) == len(e.Roster)
	require(ph == PhaseDrawable || (ph == PhaseReveal && allRevealed),
		"draw opens after the reveal window (or once every sealed ticket has revealed)")

	eligible := make([]fairness.Ticket, 0, len(e.Roster))
	leaves := make([]string, 0, len(e.Roster))
	for i := 0; i < len(e.Roster); i++ {
		t := e.Roster[i]
		if t.Secret == "" {
			continue
		}
		eligible = append(eligible, t)
		leaves = append(leaves, fairness.Leaf(t.Commit, t.Secret))
	}

	seed := fairness.Seed(e.Domain(), runtime.ChainID(), e.ID, leaves)
	winners := fairness.Draw(seed, eligible, e.Slots)

	for rank := 0; rank < len(winners); rank++ {
		idx := fairness.Find(e.Roster, winners[rank])
		if idx >= 0 {
			e.Roster[idx].Rank = rank + 1
		}
	}

	e.Seed = seed
	e.DrawnAt = now
	e.DrawnHeight = runtime.ChainHeight()

	chain.Emit("Drawn", "id", uitoa(e.ID), "seed", seed, "winners", strconv.Itoa(len(winners)))
	println("event #" + uitoa(e.ID) + " drawn, seed " + seed)
}

// Cancel voids a draw before entries close. After close the entries are
// committed and only the draw can settle them.
func Cancel(cur realm, eventID uint64) {
	runtime.AssertOriginCall()
	caller := unsafe.OriginCaller()
	e := mustEvent(eventID)

	require(caller == e.Creator, "only the organizer can cancel")
	require(!e.Cancelled, "event already cancelled")
	require(e.Seed == "", "event already drawn")
	require(e.phase(nowUnix()) == PhaseOpen, "entries are closed; the draw must settle this event")

	e.Cancelled = true
	chain.Emit("EventCancelled", "id", uitoa(e.ID))
}

// ------------------------------------------------------------------- reads

// EventCount is the number of events ever opened.
func EventCount() int {
	return len(events)
}

// Domain is this event's seal domain. It is stamped into every seal, so a seal
// cannot be moved between events, and into the seed, so a seed cannot either.
func (e *Event) Domain() string {
	return RealmPath + "#" + uitoa(e.ID)
}

// IDString renders the event id.
func (e *Event) IDString() string {
	return uitoa(e.ID)
}

// Phase returns the lifecycle phase at the given unix time.
func (e *Event) Phase(now int64) string {
	return e.phase(now)
}

func (e *Event) phase(now int64) string {
	if e.Cancelled {
		return PhaseCancelled
	}
	if e.Seed != "" {
		return PhaseDrawn
	}
	if now < e.ClosesAt {
		return PhaseOpen
	}
	if now < e.RevealEndsAt {
		return PhaseReveal
	}
	return PhaseDrawable
}

// Revealed returns how many sealed tickets have been revealed.
func (e *Event) Revealed() int {
	return revealedCount(e)
}

// Entries returns the number of sealed tickets.
func (e *Event) Entries() int {
	return len(e.Roster)
}

// Winner is one recorded winner, resolved from the roster at render time.
type Winner struct {
	Rank   int
	Entrant string
	Weight uint64
	Commit string
	Secret string
}

// Winners returns the recorded winners in rank order.
func (e *Event) Winners() []Winner {
	out := []Winner{}
	for i := 0; i < len(e.Roster); i++ {
		t := e.Roster[i]
		if t.Rank > 0 {
			out = append(out, Winner{
				Rank:    t.Rank,
				Entrant: t.ID,
				Weight:  t.Weight,
				Commit:  t.Commit,
				Secret:  t.Secret,
			})
		}
	}
	// Rank order: insertion sort, rosters are small and ranks are unique.
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Rank < out[j-1].Rank; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// Proof returns the draw's verifiable inputs as a JSON object, so an
// off-chain checker can recompute the seed and the winners from chain state
// without trusting this realm's pages. Every value is an address, a hex
// digest or a printable-ASCII secret, so the JSON needs no escaping.
func Proof(id uint64) string {
	e := mustEvent(id)

	out := "{\"event\":" + uitoa(e.ID)
	out += ",\"domain\":\"" + e.Domain() + "\""
	out += ",\"chain_id\":\"" + runtime.ChainID() + "\""
	out += ",\"slots\":" + strconv.Itoa(e.Slots)
	out += ",\"seed\":\"" + e.Seed + "\""
	out += ",\"entrants\":["
	for i := 0; i < len(e.Roster); i++ {
		t := e.Roster[i]
		if i > 0 {
			out += ","
		}
		out += "{\"address\":\"" + t.ID + "\""
		out += ",\"weight\":" + uitoa(t.Weight)
		out += ",\"seal\":\"" + t.Commit + "\""
		out += ",\"secret\":\"" + t.Secret + "\""
		out += ",\"rank\":" + strconv.Itoa(t.Rank) + "}"
	}
	out += "]}"
	return out
}

// AcceptedLeaves returns the seed inputs in fold order, for verification.
func (e *Event) AcceptedLeaves() []string {
	out := []string{}
	for i := 0; i < len(e.Roster); i++ {
		t := e.Roster[i]
		if t.Secret != "" {
			out = append(out, fairness.Leaf(t.Commit, t.Secret))
		}
	}
	return out
}

// GetEvent looks an event up by id, or nil.
func GetEvent(id uint64) *Event {
	e, ok := byID[id]
	if !ok {
		return nil
	}
	return e
}

// ---------------------------------------------------------------- internals

func revealedCount(e *Event) int {
	n := 0
	for i := 0; i < len(e.Roster); i++ {
		if e.Roster[i].Secret != "" {
			n++
		}
	}
	return n
}

func mustEvent(id uint64) *Event {
	e, ok := byID[id]
	if !ok {
		panic("event #" + uitoa(id) + " does not exist")
	}
	return e
}

func nowUnix() int64 {
	return time.Now().Unix()
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

func errString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func uitoa(u uint64) string {
	return strconv.FormatUint(u, 10)
}

func trimSpace(s string) string {
	start := 0
	end := len(s)
	for start < end && (s[start] == ' ' || s[start] == '\t' || s[start] == '\n' || s[start] == '\r') {
		start++
	}
	for end > start && (s[end-1] == ' ' || s[end-1] == '\t' || s[end-1] == '\n' || s[end-1] == '\r') {
		end--
	}
	return s[start:end]
}

// normalizeAddress accepts the shape of a bech32 gno address (g1 + 38
// lower-case alphanumerics) as typed. It deliberately does not convert through
// the address type: a bad checksum would panic, and vouching for an address
// nobody holds is harmless — the vouch just never matches a ticket.
func normalizeAddress(s string) string {
	s = trimSpace(s)
	if len(s) != 40 || s[0] != 'g' || s[1] != '1' {
		return ""
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') {
			continue
		}
		return ""
	}
	return s
}

package fairdrop

// gnoweb pages. Every page is derived from on-chain state alone, so the same
// URL renders the same thing for every visitor.

import (
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/fairness"
)

// gnowebURL turns a package path into the path part of its gnoweb URL by
// dropping the chain domain: gno.land/r/x/y -> /r/x/y.
func gnowebURL(pkgPath string) string {
	i := strings.Index(pkgPath, "/")
	if i < 0 {
		return "/" + pkgPath
	}
	return pkgPath[i:]
}

// Render dispatches gnoweb paths:
//
//	""                      board home: open and past draws
//	"event/<id>"            one draw, with the actions it accepts right now
//	"event/<id>/verify"     the seed's inputs and how to recompute it
//	"event/<id>/receipt/<rank>"
//	"create"                how to open a draw
func Render(path string) string {
	parts := strings.Split(path, "/")

	switch {
	case path == "":
		return renderHome()
	case parts[0] == "create" && len(parts) == 1:
		return renderCreate()
	case parts[0] == "event" && len(parts) == 2:
		id, ok := parseUint(parts[1])
		if !ok {
			return renderNotFound(path)
		}
		return renderEvent(id)
	case parts[0] == "event" && len(parts) == 3 && parts[2] == "verify":
		id, ok := parseUint(parts[1])
		if !ok {
			return renderNotFound(path)
		}
		return renderVerify(id)
	case parts[0] == "event" && len(parts) == 4 && parts[2] == "receipt":
		id, ok := parseUint(parts[1])
		if !ok {
			return renderNotFound(path)
		}
		rank, ok := parseUint(parts[3])
		if !ok {
			return renderNotFound(path)
		}
		return renderReceipt(id, int(rank))
	}
	return renderNotFound(path)
}

// ------------------------------------------------------------------- home

func renderHome() string {
	var b strings.Builder

	b.WriteString("# FairDrop\n\n")
	b.WriteString("Raffles whose result anyone can check.\n\n")
	b.WriteString("An organizer opens a draw with a prize and a number of winners. Entrants ")
	b.WriteString("seal a ticket by publishing only a hash of a secret they generated locally. ")
	b.WriteString("Once entries close they reveal the secret, this realm re-hashes it against the ")
	b.WriteString("seal, and when the reveal window ends **anyone** can press the draw. The winners ")
	b.WriteString("come from a seed folded out of the revealed secrets in address order, so every ")
	b.WriteString("result can be recomputed from public data — the page for each draw ends with the ")
	b.WriteString("exact inputs to do it.\n\n")

	b.WriteString("### Why it is fair\n\n")
	b.WriteString("| Step | Who acts | What is fixed at that moment |\n")
	b.WriteString("|---|---|---|\n")
	b.WriteString("| 1. Seal | each entrant | their secret and ticket weight, as a hash — unreadable until later |\n")
	b.WriteString("| 2. Close | nobody (block time) | the roster and every seal; nothing can be added or changed |\n")
	b.WriteString("| 3. Reveal | each entrant | the preimage; a reveal that does not open its own seal is rejected |\n")
	b.WriteString("| 4. Draw | anyone | the winners are a pure function of the revealed secrets |\n\n")
	b.WriteString("The organizer cannot add, drop or re-weight an entry after it is sealed, cannot ")
	b.WriteString("read the secrets before the close, and cannot see or influence the seed before ")
	b.WriteString("the reveal window. An entrant who never reveals forfeits their own ticket — it ")
	b.WriteString("cannot promote anyone else.\n\n")

	b.WriteString("## Draws\n\n")
	if len(events) == 0 {
		b.WriteString("No draw has been opened yet. ")
		b.WriteString("[Open the first one](" + gnowebURL(RealmPath) + ":create) — it takes one transaction.\n")
		return b.String()
	}

	b.WriteString("| draw | prize | entries | winners | phase | closes |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	now := nowUnix()
	for i := len(events) - 1; i >= 0; i-- {
		e := events[i]
		b.WriteString("| [#" + e.IDString() + " " + cell(e.Title) + "](" + gnowebURL(RealmPath) + ":event/" + e.IDString() + ") ")
		b.WriteString("| " + cell(e.Prize) + " ")
		b.WriteString("| " + strconv.Itoa(e.Entries()) + " sealed / " + strconv.Itoa(e.Revealed()) + " revealed ")
		b.WriteString("| " + strconv.Itoa(e.Slots) + " ")
		b.WriteString("| " + phaseBadge(e.phase(now)) + " ")
		b.WriteString("| " + closeLine(e, now) + " |\n")
	}

	b.WriteString("\n[Open a draw](" + gnowebURL(RealmPath) + ":create) · ")
	b.WriteString("the reusable engine is [" + PackagePath + "](" + gnowebURL(PackagePath) + ")\n")
	return b.String()
}

// ------------------------------------------------------------------ event

func renderEvent(id uint64) string {
	e := GetEvent(id)
	if e == nil {
		return renderNotFound("event/" + uitoa(id))
	}
	now := nowUnix()
	ph := e.phase(now)

	var b strings.Builder

	b.WriteString("# Draw #" + e.IDString() + " — " + e.Title + "\n\n")
	b.WriteString("**Prize:** " + e.Prize + "\n\n")
	b.WriteString("**Organizer:** `" + e.Creator.String() + "`\n\n")
	b.WriteString("**Winners:** " + strconv.Itoa(e.Slots) +
		" · **Max weight per ticket:** " + uitoa(e.MaxWeight) +
		" · **Phase:** " + phaseBadge(ph) + "\n\n")

	b.WriteString("### Timeline\n\n")
	b.WriteString("| phase | starts (UTC / KST) | ends (UTC / KST) | now |\n")
	b.WriteString("|---|---|---|---|\n")
	b.WriteString("| entries | " + stamp(e.OpensAt) + " | " + stamp(e.ClosesAt) + " | " + phaseTick(ph == PhaseOpen) + " |\n")
	b.WriteString("| reveal | " + stamp(e.ClosesAt) + " | " + stamp(e.RevealEndsAt) + " | " + phaseTick(ph == PhaseReveal) + " |\n")
	b.WriteString("| draw | " + stamp(e.RevealEndsAt) + " | anyone may trigger | " + phaseTick(ph == PhaseDrawn) + " |\n\n")

	if ph == PhaseOpen {
		b.WriteString("Entries close in **" + left(e.ClosesAt, now) + "**")
		if e.Entries() > 0 {
			b.WriteString(", with " + strconv.Itoa(e.Entries()) + " sealed ticket(s) so far")
		}
		b.WriteString(".\n\n")
	}
	if ph == PhaseReveal {
		b.WriteString("Reveals close in **" + left(e.RevealEndsAt, now) + "** — " +
			strconv.Itoa(e.Revealed()) + " of " + strconv.Itoa(e.Entries()) + " sealed tickets revealed.\n\n")
	}
	if ph == PhaseDrawable {
		b.WriteString("The reveal window is over. The result is fixed by the revealed secrets — ")
		b.WriteString("anyone can write it down with `Draw(" + e.IDString() + ")`.\n\n")
	}

	renderActions(&b, e, ph)
	renderRoster(&b, e, ph)
	if e.Seed != "" {
		renderResult(&b, e)
	}
	return b.String()
}

func renderActions(b *strings.Builder, e *Event, ph string) {
	b.WriteString("### Actions\n\n")
	if ph == PhaseOpen {
		b.WriteString("**Enter.** Generate a secret locally and publish only its seal:\n\n")
		b.WriteString("```sh\n")
		b.WriteString("# 1. a secret only you know (32 random bytes, hex)\n")
		b.WriteString("SECRET=$(openssl rand -hex 32)\n\n")
		b.WriteString("# 2. its seal = sha256(\"fairdrop/seal/v1|" + e.Domain() + "|<your g1 address>|<weight>|$SECRET\")\n")
		b.WriteString("SEAL=$(printf 'fairdrop/seal/v1|" + e.Domain() + "|%s|1|%s' \\\n")
		b.WriteString("  g1youraddress... \"$SECRET\" | sha256sum | cut -d' ' -f1)\n\n")
		b.WriteString("# 3. seal the ticket (weight 1 unless the organizer vouched for more)\n")
		b.WriteString("gnokey maketx call -pkgpath " + RealmPath + " -func Register \\\n")
		b.WriteString("  -args " + e.IDString() + " -args \"$SEAL\" -args 1 \\\n")
		b.WriteString("  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast \\\n")
		b.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 YOUR_KEY\n\n")
		b.WriteString("# keep $SECRET until the reveal window\n")
		b.WriteString("```\n\n")
		b.WriteString("Read the seal back on chain before the window closes: it is listed below. ")
		b.WriteString("If it is wrong, that ticket cannot be revealed and does not count.\n\n")
	} else if ph == PhaseReveal {
		b.WriteString("**Reveal.** Publish the secret behind your seal:\n\n")
		b.WriteString("```sh\n")
		b.WriteString("gnokey maketx call -pkgpath " + RealmPath + " -func Reveal \\\n")
		b.WriteString("  -args " + e.IDString() + " -args \"$SECRET\" \\\n")
		b.WriteString("  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast \\\n")
		b.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 YOUR_KEY\n")
		b.WriteString("```\n\n")
	} else if ph == PhaseDrawable {
		b.WriteString("**Draw.** Write the determined result on chain — anyone can do it:\n\n")
		b.WriteString("```sh\n")
		b.WriteString("gnokey maketx call -pkgpath " + RealmPath + " -func Draw \\\n")
		b.WriteString("  -args " + e.IDString() + " \\\n")
		b.WriteString("  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast \\\n")
		b.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 YOUR_KEY\n")
		b.WriteString("```\n\n")
	} else if ph == PhaseDrawn {
		b.WriteString("This draw is settled. [Verify it](" + gnowebURL(RealmPath) + ":event/" + e.IDString() + "/verify).\n\n")
	} else {
		b.WriteString("This draw was cancelled by its organizer before entries closed.\n\n")
	}
}

func renderRoster(b *strings.Builder, e *Event, ph string) {
	b.WriteString("### Tickets (" + strconv.Itoa(e.Entries()) + ")\n\n")
	if len(e.Roster) == 0 {
		b.WriteString("No ticket sealed yet.\n\n")
		return
	}
	b.WriteString("| # | entrant | weight | seal | status |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for i := 0; i < len(e.Roster); i++ {
		t := e.Roster[i]
		status := "sealed"
		if t.Secret != "" {
			status = "revealed"
		} else if e.phase(nowUnix()) == PhaseDrawable && e.Seed == "" {
			status = "forfeited (no reveal)"
		} else if e.Seed != "" && t.Secret == "" {
			status = "forfeited (no reveal)"
		}
		if t.Rank > 0 {
			status = "**winner #" + strconv.Itoa(t.Rank) + "**"
		}
		b.WriteString("| " + strconv.Itoa(i+1) + " | `" + t.ID + "` | " + uitoa(t.Weight) +
			" | `" + short(t.Commit) + "` | " + status + " |\n")
	}
	b.WriteString("\n")
}

func renderResult(b *strings.Builder, e *Event) {
	b.WriteString("### Result\n\n")
	winners := e.Winners()
	if len(winners) == 0 {
		b.WriteString("No eligible ticket: nobody revealed, so the draw settled with no winner.\n\n")
	} else {
		b.WriteString("| rank | winner | weight | receipt |\n")
		b.WriteString("|---|---|---|---|\n")
		for i := 0; i < len(winners); i++ {
			w := winners[i]
			b.WriteString("| " + strconv.Itoa(w.Rank) + " | `" + w.Entrant + "` | " + uitoa(w.Weight) +
				" | [receipt](" + gnowebURL(RealmPath) + ":event/" + e.IDString() + "/receipt/" + strconv.Itoa(w.Rank) + ") |\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("**Seed:** `" + e.Seed + "`\n\n")
	b.WriteString("Drawn at " + stamp(e.DrawnAt) + " at block " + strconv.FormatInt(e.DrawnHeight, 10) + ". ")
	b.WriteString("[Every input of the seed](" + gnowebURL(RealmPath) + ":event/" + e.IDString() + "/verify) is on chain.\n\n")
}

func renderVerify(id uint64) string {
	e := GetEvent(id)
	if e == nil {
		return renderNotFound("event/" + uitoa(id))
	}
	leaves := e.AcceptedLeaves()

	var b strings.Builder
	b.WriteString("# Verify draw #" + e.IDString() + "\n\n")
	b.WriteString("**Draw:** #" + e.IDString() + " · **Domain:** `" + e.Domain() + "` · **Chain:** `" + runtime.ChainID() + "`\n\n")

	if e.Seed == "" {
		b.WriteString("Not drawn yet — there is no seed to verify.\n")
		return b.String()
	}

	b.WriteString("**Seed:**\n\n```\n" + e.Seed + "\n```\n\n")
	b.WriteString("The seed is folded from these inputs, in this exact order (ascending entrant address, ")
	b.WriteString("revealed tickets only). Each leaf is `seal:secret`.\n\n")

	if len(leaves) == 0 {
		b.WriteString("_No revealed ticket, so the fold had no leaf._\n\n")
	} else {
		b.WriteString("| # | entrant | leaf |\n|---|---|---|\n")
		n := 0
		for i := 0; i < len(e.Roster); i++ {
			if e.Roster[i].Secret == "" {
				continue
			}
			n++
			b.WriteString("| " + strconv.Itoa(n) + " | `" + e.Roster[i].ID + "` | `" +
				e.Roster[i].Commit + ":" + e.Roster[i].Secret + "` |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("### Recompute it yourself\n\n")
	b.WriteString("The realm hashes this string (one trailing `|` per leaf is included):\n\n")
	b.WriteString("```\nfairdrop/seed/v1|" + e.Domain() + "|" + runtime.ChainID() + "|" + e.IDString() + "|" + strings.Join(leaves, "|") + "|\n```\n\n")
	b.WriteString("```python\nimport hashlib\n")
	b.WriteString("leaves = [" + quoteList(leaves) + "]\n")
	b.WriteString("payload = \"fairdrop/seed/v1|" + e.Domain() + "|" + runtime.ChainID() + "|" + e.IDString() + "|\" + \"\".join(l + \"|\" for l in leaves)\n")
	b.WriteString("print(hashlib.sha256(payload.encode()).hexdigest())\n")
	b.WriteString("# compare with the seed above\n")
	b.WriteString("```\n\n")

	b.WriteString("The winners are then taken from that seed by [the draw in ")
	b.WriteString("gno.land/p/fairdrop/fairness](/p/fairdrop/fairness): a SHA-256 counter-mode stream ")
	b.WriteString("walks the revealed roster in the same order, drawing weighted tickets without ")
	b.WriteString("replacement until " + strconv.Itoa(e.Slots) + " winner(s) are chosen. ")
	b.WriteString("`scripts/verify.py` in the project repository reproduces both steps.\n")
	return b.String()
}

func renderReceipt(id uint64, rank int) string {
	e := GetEvent(id)
	if e == nil {
		return renderNotFound("event/" + uitoa(id))
	}
	if e.Seed == "" {
		return "# Draw #" + e.IDString() + " has not been drawn yet\n"
	}

	found := false
	w := Winner{}
	all := e.Winners()
	for i := 0; i < len(all); i++ {
		if all[i].Rank == rank {
			w = all[i]
			found = true
			break
		}
	}
	if !found {
		return "# No winner at rank " + strconv.Itoa(rank) + " in draw #" + e.IDString() + "\n"
	}

	var b strings.Builder
	b.WriteString("# Receipt — draw #" + e.IDString() + ", rank " + strconv.Itoa(w.Rank) + "\n\n")
	b.WriteString("**Prize:** " + e.Prize + "\n\n")
	b.WriteString("**Winner:** `" + w.Entrant + "`\n\n")
	b.WriteString("**Ticket weight:** " + uitoa(w.Weight) + "\n\n")
	b.WriteString("**Seal:** `" + w.Commit + "`\n\n")
	b.WriteString("**Revealed secret:** `" + w.Secret + "`\n\n")
	b.WriteString("**Seed:** `" + e.Seed + "`\n\n")
	b.WriteString("**Drawn:** " + stamp(e.DrawnAt) + " · block " + strconv.FormatInt(e.DrawnHeight, 10) + "\n\n")
	b.WriteString("This ticket took rank " + strconv.Itoa(w.Rank) + " of " +
		strconv.Itoa(len(e.Winners())) + ", drawn from " + strconv.Itoa(e.Revealed()) +
		" revealed ticket(s) carrying " + uitoa(fairness.TotalWeight(e.Roster)) + " weight in total. ")
	b.WriteString("The receipt is checkable twice over: the secret re-hashes to the seal that was ")
	b.WriteString("on chain before entries closed, and the seed that produced this rank is the fold ")
	b.WriteString("of every revealed ticket — see [verify](" + gnowebURL(RealmPath) + ":event/" + e.IDString() + "/verify).\n")
	return b.String()
}

